(() => {
 const list=document.querySelector('#inbox-list'),status=document.querySelector('#inbox-status'),refresh=document.querySelector('#refresh-inbox');let cursor=null,busy=false;
 const labels={imovel:'Imóvel',carro:'Veículo',investir:'Planejar patrimônio',carta:'Carta contemplada',venda:'Negociar cota',mentoria:'Mentoria empresarial'};
 const credit={'nao-sei':'A conversar','ate-100k':'Até R$ 100 mil','100-300k':'R$ 100 mil a R$ 300 mil','300-600k':'R$ 300 mil a R$ 600 mil','600k-1m':'R$ 600 mil a R$ 1 milhão','mais-1m':'Acima de R$ 1 milhão'};
 const timing={planejamento:'Planejamento sem data','12-24':'Horizonte de 12 a 24 meses','avaliar-agora':'Avaliar opções agora'};
 const stage={iniciar:'Começar a operar',organizar:'Organizar a operação',desenvolver:'Desenvolver equipe e processos'};
 function add(b){const article=document.createElement('details');article.className='inbox-item';const summary=document.createElement('summary'),name=document.createElement('strong'),meta=document.createElement('span');name.textContent=b.name;meta.textContent=labels[b.interest]+' · '+new Date(b.createdAt*1000).toLocaleString('pt-BR');summary.append(name,meta);const dl=document.createElement('dl');dl.className='briefing-review';const rows=[['Referência',b.id],['WhatsApp',b.phone],...(b.email?[['E-mail',b.email]]:[]),...(b.city?[['Cidade',b.city]]:[]),...(b.interest==='mentoria'?[['Empresa',b.company],['Estágio',stage[b.businessStage]],['Equipe',b.teamSize]]:[['Crédito',credit[b.credit]],['Orçamento mensal',b.monthlyBudget?Number(b.monthlyBudget).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'A conversar'],['Momento',timing[b.timing]],['Experiência',({primeiro:'Primeiro contato',conheco:'Já conhece', 'tenho-cota':'Já tem cota'})[b.experience]]]),...(b.note?[['Observação',b.note]]:[]),['Origem',b.source],['Autorização',b.consentVersion]];for(const [k,v]of rows){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=k;dd.textContent=v;row.append(dt,dd);dl.append(row);}article.append(summary,dl);
  if(b.cpf||b.birthDate){const box=document.createElement('details');box.className='briefing-secret';const title=document.createElement('summary');title.textContent='Dados cadastrais fornecidos (acesso restrito)';box.append(title);for(const [k,v]of [['CPF',b.cpf],['Nascimento',b.birthDate]])if(v){const p=document.createElement('p');p.textContent=k+': '+v;box.append(p);}article.append(box);}
  const actions=document.createElement('div');actions.className='actions';const wa=document.createElement('a');wa.className='button dark';wa.target='_blank';wa.rel='noopener noreferrer';const phone=b.phone.replace(/\D/g,'');wa.href='https://wa.me/55'+phone+'?text='+encodeURIComponent('Olá, '+b.name.split(' ')[0]+'. Aqui é da AM Consórcios e Investimentos. Recebemos seu interesse em '+labels[b.interest].toLowerCase()+'. Podemos conversar?');wa.textContent='Iniciar atendimento no WhatsApp';actions.append(wa);article.append(actions);list.append(article);
 }
 async function load(reset=true){if(busy)return;busy=true;refresh.disabled=true;status.textContent='Carregando solicitações…';if(reset){cursor=null;list.replaceChildren();}try{const res=await fetch('/api/briefings'+(cursor?'?before='+encodeURIComponent(cursor):''),{cache:'no-store'});const data=await res.json();if(!res.ok)throw new Error(data.error||'Não foi possível carregar.');data.items.forEach(add);cursor=data.nextBefore;status.textContent=list.querySelectorAll('.inbox-item').length?list.querySelectorAll('.inbox-item').length+' briefing(s) disponível(is).':'Nenhum briefing recebido nos últimos 30 dias.';document.querySelector('.inbox-load-more')?.remove();if(cursor){const button=document.createElement('button');button.className='button dark inbox-load-more';button.textContent='Carregar mais';button.addEventListener('click',()=>load(false));list.after(button);}}catch(e){status.textContent=e.message||'Não foi possível carregar. Tente novamente.';}finally{busy=false;refresh.disabled=false;}}
 refresh.addEventListener('click',()=>load(true));load();
})();
